(function(){
var ACTIVE=['wf:bg-slate-100','wf:font-semibold','wf:text-slate-900'];
var IDLE=['wf:text-slate-600'];
function decode(value){if(!value)return null;try{var text=decodeURIComponent(Array.prototype.map.call(atob(value.replace(/-/g,'+').replace(/_/g,'/')),function(c){return '%'+('00'+c.charCodeAt(0).toString(16)).slice(-2);}).join(''));return JSON.parse(text);}catch(e){return null;}}
function encode(value){var bytes=unescape(encodeURIComponent(JSON.stringify(value)));return btoa(bytes).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function setActive(links,link){links.forEach(function(item){var on=item===link;ACTIVE.forEach(function(c){item.classList.toggle(c,on);});IDLE.forEach(function(c){item.classList.toggle(c,!on);});if(on){item.setAttribute('aria-current','true');}else{item.removeAttribute('aria-current');}});}
function pageHref(child){var route=child&&child.route?String(child.route):'';if(route.charAt(0)==='/')return route;var slug=typeof child==='string'?child:(child&&child.slug)||'';return '/baza/'+String(slug).split('/').map(function(part){return encodeURIComponent(part);}).join('/');}
document.querySelectorAll('.wf-instance[data-wf-component="kb-article"]').forEach(function(host){
if(host.dataset.kbReady==='true')return;
host.dataset.kbReady='true';
var article=host.querySelector('[data-kb-article]');
var nav=host.querySelector('[data-kb-nav]');
var status=host.querySelector('[data-kb-status]');
var form=host.querySelector('[data-kb-search]');
var query=host.querySelector('[data-kb-q]');
if(!article||!nav)return;
function clearNav(){var old=nav.querySelector('ul');if(old)old.remove();}
function paintMenu(data){
article.innerHTML='';
clearNav();
var title=document.createElement('h1');
title.className='wf:text-3xl wf:font-bold wf:tracking-tight';
title.textContent=data.title||'Baza znanja';
article.appendChild(title);
if(data.intro){var intro=document.createElement('p');intro.className='wf:mt-4 wf:text-base wf:leading-7';intro.textContent=data.intro;article.appendChild(intro);}
var list=document.createElement('ul');
list.className='wf:mt-6 wf:list-none wf:space-y-2 wf:pl-0';
(data.children||[]).forEach(function(child){
var item=document.createElement('li');
var link=document.createElement('a');
link.href=pageHref(child);
link.className='wf:block wf:rounded-lg wf:px-3 wf:py-2 wf:text-base wf:no-underline wf:text-slate-900 wf:hover:bg-slate-50';
link.textContent=child.title||child.slug;
item.appendChild(link);
list.appendChild(item);
});
if(!(data.children||[]).length){var empty=document.createElement('p');empty.className='wf:mt-4 wf:text-base wf:leading-7';empty.textContent='Nema stranica.';article.appendChild(empty);}
article.appendChild(list);
}
function paintArticle(data){
article.innerHTML='';
clearNav();
if(!data||!data.found||!data.html){var empty=document.createElement('p');empty.className='wf:mt-4 wf:text-base wf:leading-7';empty.textContent='Uputstvo još nije objavljeno.';article.appendChild(empty);return;}
article.innerHTML=data.html||'';
var heads=Array.prototype.filter.call(article.querySelectorAll('h2,h3'),function(head){return !!head.id;});
if(!heads.length)return;
var list=document.createElement('ul');
list.className='wf:mt-4 wf:list-none wf:pl-0 wf:space-y-1';
var links=[];
var lock=0;
heads.forEach(function(head){
var item=document.createElement('li');
var link=document.createElement('a');
link.href='#'+head.id;
link.className='wf:block wf:rounded-lg wf:px-3 wf:py-2 wf:text-sm wf:no-underline wf:hover:bg-slate-50 wf:text-slate-600'+(head.tagName==='H3'?' wf:pl-6':'');
link.textContent=head.textContent;
link.addEventListener('click',function(event){event.preventDefault();lock=Date.now()+900;setActive(links,link);head.scrollIntoView({behavior:'smooth',block:'start'});if(window.history&&history.replaceState){history.replaceState(null,'','#'+head.id);}});
item.appendChild(link);list.appendChild(item);links.push(link);
});
nav.appendChild(list);
var ticking=false;
function sync(){ticking=false;if(Date.now()<lock)return;var offset=140;var current=heads[0];for(var i=0;i<heads.length;i++){if(heads[i].getBoundingClientRect().top-offset<=0){current=heads[i];}else{break;}}if(window.innerHeight+window.pageYOffset>=document.documentElement.scrollHeight-2){current=heads[heads.length-1];}var link=links[heads.indexOf(current)];if(link&&link.getAttribute('aria-current')!=='true'){setActive(links,link);if(link.scrollIntoView&&nav.scrollHeight>nav.clientHeight){link.scrollIntoView({block:'nearest'});}}}
window.addEventListener('scroll',function(){if(!ticking){ticking=true;window.requestAnimationFrame(sync);}},{passive:true});
window.addEventListener('resize',sync);
var target=window.location.hash?document.getElementById(decodeURIComponent(window.location.hash.slice(1))):null;
if(target&&heads.indexOf(target)>=0){target.scrollIntoView({block:'start'});}
sync();
}
function paint(data){
if(data&&data.kind==='folder'){paintMenu(data);return;}
paintArticle(data);
}
function load(){
var path=(window.location.pathname||'/').replace(/\/+$/,'')||'/';
var extra=path.indexOf('/baza/')===0?decodeURIComponent(path.slice(6)):'';
var input=decode(host.dataset.wfProviderInput)||{};
var term=query?String(query.value||'').trim():'';
if(extra){input.slug=extra;delete input.frontpage;}else if(!input.frontpage||input.frontpage==='node'){if(!input.slug)input.slug='';}
if(!extra&&!term){var preview=decode(host.dataset.wfProviderPreview);if(preview){paint(preview);return;}}
var term=query?String(query.value||'').trim():'';
if(term){input.q=term;}else{delete input.q;}
var url=host.dataset.wfProviderUrl;
if(!url){if(status)status.textContent='Uputstvo još nije objavljeno.';return;}
var targetUrl=new URL(url,window.location.href);
targetUrl.searchParams.set('wf_input',encode(input));
fetch(targetUrl.toString(),{credentials:'same-origin',headers:{Accept:'application/json'}}).then(function(response){if(!response.ok)throw new Error('HTTP '+response.status);return response.json();}).then(function(payload){paint(payload&&payload.data?payload.data:payload);}).catch(function(){if(status)status.textContent='Uputstvo trenutno nije dostupno.';});
}
if(form){form.addEventListener('submit',function(event){event.preventDefault();load();});}
load();
});
})();
